export declare const interlaceFragment = "precision highp float;\nvarying vec2 vUv;\nuniform sampler2D eyeTexture;\nuniform vec2 outputSize,tileSize,grid;\nuniform float pitch,uTan,offset,orderMode,rotation,bgr,viewCount,eyeIndex,atlasMode;\nuniform float sourceEncoding,toneMode;\n#include <tonemapping_pars_fragment>\nfloat logical(float raw){\n  if(uTan==0.)return 14.;\n  float count=orderMode==1.?59.:30.;\n  float phase=mod(mod(raw,uTan)+uTan,uTan)/uTan;\n  float i=min(count-1.,floor(phase*count));\n  if(orderMode==2.)return 29.-i;\n  return orderMode==1.&&i>=30.?count-1.-i:i;\n}\nfloat rendered(float i){return floor(i*(viewCount-1.)/29.+.5);}\nvec3 encodeDisplay(vec3 c){\n  if(sourceEncoding==1.)return c;\n  if(sourceEncoding!=2.){\n    if(toneMode==2.)c=ACESFilmicToneMapping(c);\n    else if(toneMode==1.)c=ReinhardToneMapping(c);\n    else c*=toneMappingExposure;\n  }\n  c=max(c,vec3(0.));\n  return mix(1.055*pow(c,vec3(1./2.4))-.055,12.92*c,lessThanEqual(c,vec3(.0031308)));\n}\nvec3 sampleEye(float index){\n  vec2 cell=atlasMode>.5?vec2(mod(index,grid.x),floor(index/grid.x)):vec2(0.);\n  vec2 pixel=vec2(.5)+clamp(vUv,0.,1.)*(tileSize-1.);\n  return encodeDisplay(texture2D(eyeTexture,(cell*tileSize+pixel)/(grid*tileSize)).rgb);\n}\nvoid main(){\n  if(viewCount==1.){gl_FragColor=vec4(sampleEye(0.),1.);return;}\n  vec2 p=vec2(floor(gl_FragCoord.x),outputSize.y-1.-floor(gl_FragCoord.y));\n  vec2 size=outputSize;\n  if(rotation==90.){p=vec2(p.y,size.x-1.-p.x);size=size.yx;}\n  else if(rotation==180.)p=size-1.-p;\n  else if(rotation==270.){p=vec2(size.y-1.-p.y,p.x);size=size.yx;}\n  float base=offset+p.y*3.*pitch+(size.x-1.-p.x)*3.;\n  vec3 indices=vec3(rendered(logical(base+(bgr>.5?0.:2.))),rendered(logical(base+1.)),rendered(logical(base+(bgr>.5?2.:0.))));\n  if(atlasMode>.5){gl_FragColor=vec4(sampleEye(indices.r).r,sampleEye(indices.g).g,sampleEye(indices.b).b,1.);return;}\n  vec3 mask=vec3(indices.r==eyeIndex?1.:0.,indices.g==eyeIndex?1.:0.,indices.b==eyeIndex?1.:0.);\n  if(dot(mask,vec3(1.))<.5)discard;\n  gl_FragColor=vec4(sampleEye(eyeIndex)*mask,0.);\n}";
